import React from 'react';
import { Link } from 'react-router-dom'; // Import Link from react-router-dom
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { Carousel } from 'react-responsive-carousel';
import "react-responsive-carousel/lib/styles/carousel.min.css"; // Import carousel styles

function Photography() {
    const { ref, inView } = useInView();

    // Image arrays
    const bmImages = [
        "/bm1.avif",
        "/bm2.avif",
        "/bm3.avif",
        "/bm4.avif",
        "/bm5.avif",
        "/bm6.avif",
        "/bm7.avif"
    ];

    const carouselImages = [
        "/carousel1.avif",
        "/carousel2.avif",
        "/carousel3.avif",
        "/carousel4.avif",
        "/carousel5.avif",
        "/carousel6.avif",
        "/carousel7.avif",
        "/carousel8.avif",
        "/carousel9.avif",
        "/carousel10.avif"
    ];

    return (
        <div className="p-5 sm:p-8 md:p-10 lg:p-16 flex flex-col items-center text-center">
            {/* Back Button and Heading */}
            <div className="w-full flex items-center justify-between">
                <p className="underline text-base sm:text-lg md:text-xl lg:text-2xl cursor-pointer pl-5">Go Back</p>
                <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold flex-1 text-center">Photography</h1>
            </div>

            {/* Description */}
            <p className="text-sm sm:text-base md:text-lg pl-2 sm:pl-5 mt-4 w-full sm:w-3/4 lg:w-1/2 break-words sm:whitespace-normal whitespace-pre-line ml-10">
                Some of my best photography over the course of 2 years.
            </p>

            {/* Image Carousel - BM Images */}
            <div className="bg-black flex flex-col items-center justify-center text-white w-full py-20 space-y-4">
                <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold text-center text-white">My Photography</h2>
                <Carousel
                    autoPlay
                    infiniteLoop
                    showThumbs={false}
                    showStatus={false}
                    interval={3000}
                    showArrows
                    className="w-full md:w-3/4 lg:w-2/3"
                >
                    {bmImages.map((image, index) => (
                        <div key={index} className="flex justify-center">
                            <img
                                src={image}
                                alt={`BM Image ${index + 1}`}
                                className="w-full h-auto object-contain max-h-[500px]" // Adjusted size
                            />
                        </div>
                    ))}
                </Carousel>
            </div>

            {/* Image Carousel - Carousel Images */}
            <div className="bg-black flex flex-col items-center justify-center text-white w-full py-20 space-y-4">
                <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold text-center text-white">More of My Photography</h2>
                <Carousel
                    autoPlay
                    infiniteLoop
                    showThumbs={false}
                    showStatus={false}
                    interval={3000}
                    showArrows
                    className="w-full md:w-3/4 lg:w-2/3"
                >
                    {carouselImages.map((image, index) => (
                        <div key={index} className="flex justify-center">
                            <img
                                src={image}
                                alt={`Carousel Image ${index + 1}`}
                                className="w-full h-auto object-contain max-h-[500px]" // Adjusted size
                            />
                        </div>
                    ))}
                </Carousel>
            </div>
        </div>
    );
}

export default Photography;
